# Oracle cases (design 11): tests/testthat/oracle/<Type>.json, generated by
# tools/temporal-oracle/generate.js from temporal-polyfill. oracle_cases()
# reads a file; a type's test file loops over the cases and hands each to
# oracle_check(), which maps the JavaScript member to the R function of
# design 5, runs it, and compares the outcome with the engine's.

oracle_cases <- function(type) {
  skip_if_not_installed("jsonlite")
  path <- test_path("oracle", paste0(type, ".json"))
  doc <- jsonlite::fromJSON(path, simplifyVector = FALSE)
  stopifnot(identical(doc$type, type))
  doc$cases
}

# The condition class a JavaScript error class maps to (design 10).
oracle_error_class <- function(js) {
  switch(
    js,
    RangeError = "zutempo_range_error",
    TypeError = "zutempo_type_error",
    stop("unmapped JavaScript error class: ", js)
  )
}

# camelCase to the snake_case of design 5.
oracle_snake <- function(name) {
  name <- gsub("([a-z0-9])([A-Z])", "\\1_\\2", name)
  name <- gsub("([A-Z]+)([A-Z][a-z])", "\\1_\\2", name)
  tolower(name)
}

oracle_fn <- function(name) {
  get(name, envir = asNamespace("zutempo"))
}

# The R constructor of a Temporal type.
oracle_constructor <- function(type) {
  oracle_fn(oracle_snake(type))
}

# A JSON argument as the R function wants it: a typed value is built with
# its constructor, a bag of fields becomes named arguments (returned as a
# list to splice), anything else passes through.
oracle_arg <- function(arg) {
  if (is.list(arg) && !is.null(arg[["$type"]])) {
    return(oracle_constructor(arg[["$type"]])(arg[["value"]]))
  }
  if (is.list(arg)) {
    names(arg) <- oracle_snake(names(arg))
    return(arg)
  }
  arg
}

oracle_options <- function(case) {
  opts <- case[["options"]]
  if (is.null(opts)) {
    return(list())
  }
  names(opts) <- oracle_snake(names(opts))
  opts
}

# Skip a case whose type a later stage builds.
oracle_skip_until_built <- function(type) {
  constructor <- oracle_snake(type)
  stage <- c(
    plain_date = 2L,
    plain_time = 2L,
    plain_date_time = 2L,
    plain_year_month = 3L,
    plain_month_day = 3L,
    duration = 4L,
    instant = 5L,
    zoned_date_time = 7L
  )[[constructor]]
  if (!exists(constructor, envir = asNamespace("zutempo"), inherits = FALSE)) {
    skip(sprintf(
      "%s() arrives in stage %d of .agents/roadmap.md",
      constructor,
      stage
    ))
  }
}

# Run the member of a case and return its value, or raise its condition.
# A field bag among the arguments becomes named arguments; a string that
# names a unit (round()) becomes `smallest_unit`.
oracle_run <- function(type, case) {
  constructor <- oracle_constructor(type)
  args <- lapply(case[["args"]], oracle_arg)
  options <- oracle_options(case)
  splice <- function(args) {
    out <- list()
    for (a in args) {
      if (is.list(a)) out <- c(out, a) else out <- c(out, list(a))
    }
    out
  }
  if (is.null(case[["on"]])) {
    fn <- if (identical(case[["op"]], "from")) {
      constructor
    } else {
      oracle_fn(paste(
        oracle_snake(type),
        oracle_snake(case[["op"]]),
        sep = "_"
      ))
    }
    return(do.call(fn, c(splice(args), options)))
  }
  x <- constructor(case[["on"]])
  fn <- oracle_fn(paste0("temporal_", oracle_snake(case[["op"]])))
  if (
    identical(case[["op"]], "round") && length(args) && is.character(args[[1L]])
  ) {
    args[[1L]] <- list(smallest_unit = args[[1L]])
  }
  do.call(fn, c(list(x), splice(args), options))
}

# Compare an R value with the engine's description of its result.
oracle_expect_result <- function(value, result) {
  if (!is.list(result)) {
    # A number, string or boolean.
    if (is.logical(result)) {
      expect_identical(value, result)
    } else if (is.numeric(result)) {
      expect_equal(as.numeric(value), result)
    } else {
      expect_identical(value, result)
    }
    return(invisible())
  }
  expect_identical(oracle_fn("temporal_to_string")(value), result[["string"]])
  if (!is.null(result[["type"]])) {
    expect_s3_class(value, paste0("zutempo_", oracle_snake(result[["type"]])))
  }
  for (name in names(result[["fields"]])) {
    accessor <- oracle_fn(oracle_snake(name))
    expected <- result[["fields"]][[name]]
    if (is.null(expected)) {
      # JavaScript's undefined (era and eraYear in the ISO calendar).
      expect_true(is.na(accessor(value)), info = name)
    } else {
      expect_equal(accessor(value), expected, info = name, ignore_attr = TRUE)
    }
  }
  invisible()
}

oracle_check <- function(type, case) {
  oracle_skip_until_built(type)
  if (!is.null(case[["throws"]])) {
    expect_error(
      oracle_run(type, case),
      class = oracle_error_class(case[["throws"]])
    )
    return(invisible())
  }
  oracle_expect_result(oracle_run(type, case), case[["result"]])
}
